public static unsafe class RpcInit
{
    public const uint Flags = AkRpc.AK_INIT_NO_CRYPTO | AkRpc.AK_INIT_NO_PANIC_HOOK;
    public static int Code { get; private set; } = int.MinValue;
    public static void Ensure() => RuntimeHelpers.RunClassConstructor(typeof(AkRpc).TypeHandle);
    internal static void Run()
    {
        if (Environment.GetEnvironmentVariable("AK_GATE_PLANT_NO_INIT") == "1") { Code = -999; return; }
        var o = new ak_init_opts { abi_version = AkRpc.AK_ABI_VERSION, flags = Flags };
        var e = new ak_err();
        int rc = AkRpc.ak_init(&o, &e);
        Code = rc;
        if (rc != AkRpc.AK_OK && rc != AkRpc.AK_ALREADY_INITIALIZED)
            throw new InvalidOperationException($"ak_init failed: {rc} (code {e.code}, detail {e.detail})");
    }
}

public static unsafe class RpcLayout
{
    private static int Fsz<T>(T* _) where T : unmanaged => sizeof(T);
    public static List<(string Name, int Size, int Fields, List<(string Name, int Off, int Size)> F)> Table()
    {
        var all = new List<(string, int, int, List<(string, int, int)>)>();
        {
            var v = default(ak_bytes); ak_bytes* z = &v; var f = new List<(string, int, int)>();
            f.Add(("ptr", (int)((byte*)&z->ptr - (byte*)z), Fsz(&z->ptr)));
            f.Add(("len", (int)((byte*)&z->len - (byte*)z), Fsz(&z->len)));
            f.Add(("owner", (int)((byte*)&z->owner - (byte*)z), Fsz(&z->owner)));
            all.Add(("ak_bytes", sizeof(ak_bytes), typeof(ak_bytes).GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic).Length, f));
        }
        {
            var v = default(ak_completion); ak_completion* z = &v; var f = new List<(string, int, int)>();
            f.Add(("tag", (int)((byte*)&z->tag - (byte*)z), Fsz(&z->tag)));
            f.Add(("status", (int)((byte*)&z->status - (byte*)z), Fsz(&z->status)));
            f.Add(("bytes", (int)((byte*)&z->bytes - (byte*)z), Fsz(&z->bytes)));
            all.Add(("ak_completion", sizeof(ak_completion), typeof(ak_completion).GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic).Length, f));
        }
        {
            var v = default(ak_client_opts); ak_client_opts* z = &v; var f = new List<(string, int, int)>();
            f.Add(("stream_window", (int)((byte*)&z->stream_window - (byte*)z), Fsz(&z->stream_window)));
            f.Add(("connection_window", (int)((byte*)&z->connection_window - (byte*)z), Fsz(&z->connection_window)));
            f.Add(("adaptive_window", (int)((byte*)&z->adaptive_window - (byte*)z), Fsz(&z->adaptive_window)));
            f.Add(("max_recv_message", (int)((byte*)&z->max_recv_message - (byte*)z), Fsz(&z->max_recv_message)));
            f.Add(("max_send_message", (int)((byte*)&z->max_send_message - (byte*)z), Fsz(&z->max_send_message)));
            f.Add(("tcp_nagle", (int)((byte*)&z->tcp_nagle - (byte*)z), Fsz(&z->tcp_nagle)));
            all.Add(("ak_client_opts", sizeof(ak_client_opts), typeof(ak_client_opts).GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic).Length, f));
        }
        {
            var v = default(ak_rpc_counters); ak_rpc_counters* z = &v; var f = new List<(string, int, int)>();
            f.Add(("forward", (int)((byte*)&z->forward - (byte*)z), Fsz(&z->forward)));
            f.Add(("reverse", (int)((byte*)&z->reverse - (byte*)z), Fsz(&z->reverse)));
            all.Add(("ak_rpc_counters", sizeof(ak_rpc_counters), typeof(ak_rpc_counters).GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic).Length, f));
        }
        {
            var v = default(ak_init_opts); ak_init_opts* z = &v; var f = new List<(string, int, int)>();
            f.Add(("abi_version", (int)((byte*)&z->abi_version - (byte*)z), Fsz(&z->abi_version)));
            f.Add(("flags", (int)((byte*)&z->flags - (byte*)z), Fsz(&z->flags)));
            f.Add(("log", (int)((byte*)&z->log - (byte*)z), Fsz(&z->log)));
            f.Add(("log_ctx", (int)((byte*)&z->log_ctx - (byte*)z), Fsz(&z->log_ctx)));
            all.Add(("ak_init_opts", sizeof(ak_init_opts), typeof(ak_init_opts).GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic).Length, f));
        }
        {
            var v = default(ak_err); ak_err* z = &v; var f = new List<(string, int, int)>();
            f.Add(("code", (int)((byte*)&z->code - (byte*)z), Fsz(&z->code)));
            f.Add(("detail", (int)((byte*)&z->detail - (byte*)z), Fsz(&z->detail)));
            all.Add(("ak_err", sizeof(ak_err), typeof(ak_err).GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic).Length, f));
        }
        return all;
    }
